def check_airport_code(S: str, T: str) -> str:
    def is_subsequence(small, large):
        it = iter(large)
        return all(c in it for c in small)

    # Check if T can be formed by a subsequence of length 3
    if is_subsequence(T.lower(), S):
        return "Yes"

    # Check if T can be formed by a subsequence of length 2 and appending 'X'
    if T[-1] == 'X' and is_subsequence(T[0:2].lower(), S):
        return "Yes"

    return "No"

# Example usage:
S = input()
T = input()
print(check_airport_code(S, T))
